const width = inputs.controls?.width ?? params.width;
if (!Number.isInteger(width) || width < 1 || width > 64) throw new Error('width must be an integer from 1 to 64');
console.log('Creating trainable architecture with', width, 'hidden features');
return {layers: [
  {type: 'Linear', in_features: 1, out_features: width, bias: true},
  {type: 'RMSNorm', normalized_shape: width, eps: 0.000001},
  {type: 'GELU'},
  {type: 'Linear', in_features: width, out_features: 1, bias: true}
]};
